"""Cuaderno del estudiante, 3.º básico Lenguaje y Comunicación: OA 13 (escribir narraciones) y OA 14 (escribir artículos informativos)."""
from __future__ import annotations

from student_content_le3_b import reg
from student_lessons import ex

OA13, OA14 = "LE03 OA 13", "LE03 OA 14"
E = ex

HECHOS_AGUA = ("Datos sobre el agua: a) El agua se usa para beber. b) El hielo es agua en estado sólido. c) Con agua se riegan las plantas. "
               "d) El vapor es agua en estado gaseoso. e) Con agua se lava la ropa. f) El agua de un vaso es líquida. "
               "g) El agua se usa para cocinar. h) El hielo se derrite con el calor y se vuelve líquido.")

# ================================================================ OA 13 · escribir narraciones
reg(
    OA13, 1,
    "Este cuaderno, lápiz y los planes escritos en los ejercicios. Sin materiales especiales.",
    "Aprenderé a planificar un cuento pensando en el personaje, el lugar y el problema. Sirve para empezar a escribir con una idea clara.",
    ["Sé que un cuento tiene personajes.", "Sé escribir oraciones completas."],
    ["Una narración cuenta lo que le pasa a un personaje. Puede ser una experiencia personal (algo que te pasó), un relato de hechos (algo que ocurrió, contado en orden) o un cuento (una historia inventada). Antes de escribirla conviene hacer un plan. El plan responde tres preguntas: ¿quién es el personaje?, ¿dónde está? y ¿qué problema tiene? El problema se llama conflicto y es lo que hace que la historia siga.",
     "Un cuento tiene tres partes. El inicio presenta al personaje, el lugar y la situación. El desarrollo cuenta lo que hace el personaje para resolver el problema. El desenlace muestra cómo termina. Sin conflicto no hay historia: «Ema tiene un gato» es solo un dato; «Ema perdió a su gato en el parque» ya es una historia.",
     "Al planificar, escribe tus ideas en pocas palabras. No resuelvas el conflicto de golpe: si Pedro pierde su gorro y lo encuentra al instante, no hay historia. El personaje debe intentar algo y tener dificultades antes del final."],
    [("narración", "texto que cuenta hechos que le pasan a un personaje"), ("conflicto", "problema que tiene el personaje"), ("inicio", "parte que presenta personaje, lugar y situación"), ("desarrollo", "parte donde el personaje actúa para resolver el problema"), ("desenlace", "parte final donde se resuelve el problema")],
    [("Armar el plan", "Idea: Tomás perdió su pelota en el techo del vecino. ¿Cuál es el personaje, el lugar y el problema?", ["El personaje es quien vive la historia: Tomás.", "El lugar es donde pasa: el techo del vecino.", "El problema es que perdió su pelota."], "Personaje: Tomás. Lugar: el techo del vecino. Problema: perdió su pelota"),
     ("Distinguir dato y conflicto", "«Ema tiene un gato» o «Ema perdió a su gato en el parque». ¿Cuál tiene conflicto?", ["La primera solo da un dato.", "La segunda tiene un problema: perdió al gato.", "Elijo la segunda."], "Ema perdió a su gato en el parque")],
    [("Contar un cuento sin problema.", "Sin conflicto no pasa nada interesante.", "Agrega algo que el personaje deba resolver."), ("Resolver el conflicto en una sola línea.", "No hay desarrollo.", "Haz que el personaje intente varias cosas.")],
    ([E("En «Lola quiere cruzar el río, pero no sabe nadar», ¿quién es el personaje?", "Lola", "Es quien vive la situación."),
      E("En «Lola quiere cruzar el río, pero no sabe nadar», ¿cuál es el problema?", "Que no sabe nadar", "Le impide cruzar."),
      E("¿Qué parte del cuento presenta al personaje y el lugar: el inicio o el desenlace?", "El inicio", "Ahí se presenta la situación.")],
     [E("¿Cómo se llama el problema que tiene el personaje?", "Conflicto", "Es lo que hace avanzar la historia."),
      E("¿Qué parte cuenta lo que hace el personaje para resolver el problema: el desarrollo o el inicio?", "El desarrollo", "Ahí actúa el personaje."),
      E("Escribirás lo que te pasó ayer en el recreo, contado en orden. ¿Qué tipo de narración es: una experiencia personal o un cuento inventado?", "Una experiencia personal", "Cuenta algo que te pasó de verdad.")],
     [E("Plan: personaje Sofía, lugar la plaza. Falta el problema. ¿Cuál sirve: «A Sofía le gusta la plaza» o «A Sofía se le cayó su helado cerca de un perro»?", "A Sofía se le cayó su helado cerca de un perro", "Es un problema que se puede resolver."),
      E("Tres ideas: A) Un niño pierde la llave de su casa. B) Una niña mira el cielo. C) Un gato queda atrapado en un árbol. ¿Cuántas tienen un conflicto claro?", "2", "A y C tienen un problema que resolver."),
      E("Plan: personaje Tomás, problema pierde su pelota. ¿Qué falta para el plan: el lugar o el nombre del autor?", "El lugar", "El plan tiene personaje, lugar y problema.")],
     [E("Pedro perdió su gorro y lo encontró al instante, en la misma línea. ¿Qué parte faltó: el desarrollo o el título?", "El desarrollo", "No intentó ni buscó nada."),
      E("Ana dice que «Había una niña que vivía en un pueblo» ya es un cuento completo. ¿Qué le falta?", "Un conflicto y lo que pasa después", "Solo presenta un personaje y un lugar.")],
     [E("Elige el plan más completo: A) «Mateo y su perro.» B) «Mateo, en el cerro, pierde a su perro y lo busca.» C) «Mateo va al cerro.»", "B", "Tiene personaje, lugar y problema."),
      E("Una niña va en un bus lleno de gente. ¿Cuál es un problema para su cuento: A) «Se le cayó la mochila y no puede agacharse a recogerla», B) «Va sentada y mira por la ventana», C) «El bus es azul»?", "A", "A es un problema que ella debe resolver; B y C no tienen conflicto.")]),
    [E("Quieres escribir un cuento sobre un niño en un día de lluvia. ¿Qué problema le das: «Le gusta la lluvia» o «Se le olvidó el paraguas lejos de su casa»?", "Se le olvidó el paraguas lejos de su casa", "Es un problema que él debe resolver.")],
    [E("¿Un cuento necesita un conflicto?", "Sí", "Sin conflicto no hay historia."),
     E("¿El inicio presenta al personaje y el lugar?", "Sí", "Es la primera parte."),
     E("¿Debo resolver el problema en la primera línea?", "No", "El personaje debe intentar varias cosas.")],
    ("Elige una de estas ideas: A) Una niña descubre que su paraguas no se abre en medio de la lluvia. B) Un niño pierde la llave de su casa antes de entrar. C) Un gato queda atrapado en un árbol. Escribe el plan de tu cuento en tres líneas: personaje, lugar y problema.", "B. Personaje: Mateo. Lugar: la puerta de su casa. Problema: perdió la llave y no puede entrar.", ["elige una de las tres ideas", "nombra el personaje", "nombra el lugar", "escribe un problema claro"], ["plan de tres líneas"], ["escribir solo el tema", "resolver el problema en el plan"], "Lee tu plan a otra persona y pregúntale qué crees que pasará después."),
    "Escribe un plan de cuento con personaje, lugar y problema sobre un niño y su bicicleta.",
    "Toma la idea C y escribe dos problemas distintos que podría tener el gato.")

reg(
    OA13, 2,
    "Este cuaderno, lápiz y las oraciones escritas en los ejercicios. Sin materiales especiales.",
    "Aprenderé a ordenar las acciones de un cuento con conectores y a mostrar por qué ocurren. Sirve para que el lector entienda la secuencia de la historia.",
    ["Sé planificar un cuento.", "Sé que un cuento tiene inicio, desarrollo y desenlace."],
    ["En un cuento las acciones van en un orden. Los conectores son palabras que unen las ideas y ayudan a seguir ese orden. Para ordenar en el tiempo usamos: primero, luego, después, de pronto, mientras, al final. Para decir por qué pasó algo usamos: porque, por eso, entonces.",
     "Cada acción debe tener una causa. Por ejemplo: «Mateo pateó la pelota muy fuerte, por eso cayó en el techo del vecino». La causa es que pateó fuerte; la consecuencia es que la pelota cayó. Si las acciones no tienen relación, la historia suena como una lista.",
     "Para revisar el orden, pregúntate: ¿qué pasó primero?, ¿qué pasó después?, ¿por qué pasó? Si cambias el orden y el cuento ya no se entiende, el orden estaba bien. Los conectores correctos hacen que la historia sea coherente, es decir, que todo calce."],
    [("conector", "palabra que une ideas y muestra orden o causa"), ("secuencia", "orden en que ocurren los hechos"), ("causa", "lo que hace que algo ocurra"), ("consecuencia", "lo que ocurre por esa causa"), ("coherente", "que todas las partes calzan entre sí")],
    [("Ordenar la secuencia", "Ordena: 1) Mateo tocó el timbre del vecino. 2) Mateo pateó la pelota. 3) La pelota cayó al techo. 4) El vecino le ayudó.", ["Lo primero que pasó fue patear la pelota.", "Después cayó al techo.", "Luego Mateo tocó el timbre y al final el vecino ayudó."], "2, 3, 1, 4"),
     ("Elegir el conector de causa", "«Llovía mucho, ___ Sofía llevó paraguas.» ¿Va «por eso» o «pero»?", ["La lluvia es la causa.", "Llevar paraguas es la consecuencia.", "Va «por eso»."], "Por eso")],
    [("Poner conectores de tiempo cuando necesito uno de causa.", "El lector no entiende por qué pasó.", "Si explicas por qué, usa porque o por eso."), ("Contar acciones sin relación entre sí.", "Parece una lista.", "Cada acción debe llevar a la siguiente.")],
    ([E("¿Qué conector va primero en una secuencia: primero o al final?", "Primero", "Marca el inicio del orden."),
      E("«Sofía llevó paraguas ___ llovía.» ¿Va «porque» o «pero»?", "Porque", "Llovía es la causa."),
      E("Ordena con números: 1) La pelota cayó al techo. 2) Mateo pateó la pelota. ¿Cuál va primero?", "Mateo pateó la pelota", "Sin patear, la pelota no cae.")],
     [E("¿Para qué sirve un conector en un cuento?", "Para unir las ideas y mostrar su orden o causa", "Ayuda a seguir la historia."),
      E("En «Tenía hambre, por eso abrió el refrigerador», ¿cuál es la causa?", "Que tenía hambre", "Lo que explica la acción."),
      E("¿Qué conector sirve para decir que algo pasó de repente: de pronto o primero?", "De pronto", "Indica una sorpresa.")],
     [E("Ordena: 1) Ema se puso las botas. 2) Ema salió a pisar charcos. 3) Llovió toda la mañana. 4) Ema miró por la ventana. Escribe los números en orden.", "3, 4, 1, 2", "Primero llovió, luego miró, se puso las botas y salió."),
      E("«Estaba oscuro, ___ Lola prendió la linterna.» ¿Va «por eso» o «mientras»?", "Por eso", "Oscuridad es la causa."),
      E("Une con el conector que falta: «Pedro se cayó ___ corría sobre el piso mojado.» Opciones: porque, después.", "Porque", "Correr sobre el piso mojado explica la caída.")],
     [E("Un niño escribe: «Camila corrió. Hacía calor. Comió una manzana». ¿Qué falta para que tengan relación?", "Conectores que muestren causa y orden", "Sin conectores es una lista."),
      E("Tomás escribió: «Primero se durmió, luego se levantó y finalmente se acostó para dormirse». ¿Se entiende bien la secuencia?", "No; se durmió antes de acostarse", "El orden no es lógico.")],
     [E("Completa con el conector adecuado: «Sofía se cayó de la bicicleta, ___ le dolió la rodilla.» ¿Va «por eso» o «mientras»?", "Por eso", "El dolor es consecuencia de la caída."),
      E("Un niño se mojó. ¿Cuál oración une bien la causa y la consecuencia con «porque»: A) «Se mojó porque olvidó el paraguas», B) «Olvidó el paraguas porque se mojó»?", "A", "La causa es olvidar el paraguas y la consecuencia es mojarse; en B se invierten.")]),
    [E("Escribes: «Mateo pateó la pelota. ___ cayó en el techo.» ¿Qué conector va: «Entonces» o «Antes»?", "Entonces", "Muestra lo que pasó después por esa causa.")],
    [E("¿«Por eso» sirve para decir una consecuencia?", "Sí", "Une causa y consecuencia."),
     E("¿«Primero» y «finalmente» muestran orden?", "Sí", "Son conectores de tiempo."),
     E("¿Un cuento puede ser solo una lista de acciones sin relación?", "No", "Debe ser coherente.")],
    ("Ordena estas seis acciones del cuento y escríbelas en un párrafo con conectores (primero, luego, de pronto, por eso, al final): a) El cuaderno se secó. b) Luis encontró una caja en el patio. c) Luis lo puso a secar al sol. d) Luis llevó el cuaderno a un lugar seco. e) Dentro de la caja había un cuaderno mojado por la lluvia. f) Al final Luis pudo leerlo otra vez. Escribe el párrafo.", "Primero, Luis encontró una caja en el patio. Dentro había un cuaderno mojado por la lluvia, por eso lo llevó a un lugar seco. Luego lo puso a secar al sol...", ["ordena las acciones lógicamente", "usa al menos tres conectores", "una acción explica la siguiente", "cuenta las seis acciones"], ["párrafo escrito"], ["usar siempre «y»", "cambiar el orden lógico"], "Lee tu párrafo a otra persona y pregúntale si siguió la historia."),
    "Escribe tres oraciones con los conectores primero, luego y al final sobre cómo te lavas las manos.",
    "Reescribe «Llovía. Salí» uniéndolo con porque y con por eso.")

reg(
    OA13, 3,
    "Este cuaderno, lápiz y los textos escritos en los ejercicios. Sin materiales especiales.",
    "Aprenderé a describir a un personaje y el lugar donde ocurre la historia con detalles. Sirve para que el lector imagine a quién le pasa algo y dónde.",
    ["Sé planificar un cuento.", "Sé usar detalles de los sentidos."],
    ["Un personaje es quien vive la historia. Para presentarlo puedes decir cómo es (valiente, tímido), qué hace y qué dice. Por ejemplo, «Lola dudó un momento y luego dio un paso al frente» muestra que es valiente sin escribir la palabra «valiente».",
     "El ambiente es el lugar y el momento donde ocurre la historia. Puede ser un bosque de noche, un patio en verano, una cocina de mañana. Los detalles del ambiente crean sensaciones: «un bosque oscuro y silencioso» da miedo; «una cocina con olor a pan» da calma.",
     "Elige pocos detalles, pero precisos. No hace falta describir todo. Escoge los que sirven para la historia: si el personaje tiene miedo, el ambiente puede ser oscuro. Así el personaje y el ambiente se apoyan."],
    [("personaje", "quien vive la historia"), ("ambiente", "lugar y momento donde ocurre la historia"), ("describir", "decir cómo es algo con detalles"), ("tímido", "que le da vergüenza hablar o mostrarse")],
    [("Mostrar cómo es un personaje", "Quieres decir que Pedro es tímido sin escribir la palabra. ¿Qué acción sirve: «Pedro se escondió detrás de su mamá» o «Pedro corrió a saludar a todos»?", ["Tímido es sentir vergüenza.", "Esconderse muestra vergüenza.", "Elijo la primera."], "Pedro se escondió detrás de su mamá"),
     ("Elegir el ambiente", "Cuento de miedo: ¿qué ambiente ayuda: «un bosque oscuro y silencioso» o «una plaza con música y risas»?", ["El miedo se apoya en lo oscuro.", "El silencio da misterio.", "Elijo el bosque."], "Un bosque oscuro y silencioso")],
    [("Decir solo «era valiente» sin mostrarlo.", "El lector no lo ve.", "Muestra lo que hace o dice."), ("Describir tantos detalles que se pierde la historia.", "Cansa al lector.", "Elige los que sirven para el cuento.")],
    ([E("«Lola dudó, pero dio un paso al frente.» ¿Qué muestra de Lola: valentía o timidez?", "Valentía", "Actúa aunque duda."),
      E("¿Cómo se llama el lugar y momento donde ocurre la historia?", "Ambiente", "Es donde y cuándo pasa."),
      E("«Pedro se escondió detrás de su mamá.» ¿Qué sentimiento muestra?", "Vergüenza (timidez)", "Esconderse indica timidez.")],
     [E("¿Qué es mejor para mostrar cómo es un personaje: lo que hace o solo decir una palabra?", "Lo que hace", "Se ve en acciones."),
      E("¿Un bosque oscuro y silencioso da sensación de miedo o de alegría?", "Miedo", "La oscuridad y el silencio dan inquietud."),
      E("¿Para qué sirven los detalles del ambiente?", "Para crear sensaciones y ayudar a imaginar el lugar", "Hacen que el lector sienta la escena.")],
     [E("Quieres un ambiente tranquilo en la mañana. ¿Cuál sirve: «Olía a pan tostado y la luz entraba por la ventana» o «Sonaban sirenas por todas partes»?", "Olía a pan tostado y la luz entraba por la ventana", "Da una sensación de calma."),
      E("¿Qué acción muestra que un niño está contento sin decir «contento»: A) «Saltó y aplaudió», B) «Se quedó mirando el suelo en silencio», C) «Dijo: estoy contento»?", "A", "A muestra alegría con acciones; B muestra tristeza y C usa la palabra."),
      E("«Ema era una niña curiosa: abría todas las cajas para ver qué había dentro.» ¿Qué acción muestra que es curiosa?", "Abría todas las cajas", "Quiere saber qué hay dentro.")],
     [E("Beto escribió: «Ana era muy simpática». ¿Qué cambio es mejor: «Ana era muy, muy simpática» o «Ana saludaba a todos con una sonrisa»?", "Ana saludaba a todos con una sonrisa", "Muestra la simpatía con una acción."),
      E("Un cuento de miedo ocurre en una plaza con música y risas. ¿Qué cambias para ayudar al miedo: el ambiente o el nombre del personaje?", "El ambiente", "La música alegre quita el miedo.")],
     [E("¿Cuál describe con dos detalles de ambiente una cocina de noche: A) «Estaba oscura y solo se oía el refrigerador», B) «Había una fiesta con música fuerte y mucha luz», C) «Ema era muy valiente»?", "A", "A nombra dos detalles del lugar y del momento; B es un ambiente de fiesta y C describe a un personaje."),
      E("Un cuento dice: «Era de noche en el cerro y soplaba un viento frío. Tomás sintió un escalofrío». ¿Cuántos detalles de ambiente hay: 2 o 3?", "3", "Son noche, cerro y viento frío.")]),
    [E("Cuentas la historia de un gato en un callejón de noche. ¿Qué detalle de ambiente sirve: «un callejón estrecho con poca luz» o «una fiesta con globos»?", "Un callejón estrecho con poca luz", "Calza con la noche.")],
    [E("¿Se puede mostrar cómo es un personaje sin nombrar su rasgo?", "Sí", "Con lo que hace y dice."),
     E("¿El ambiente es solo el lugar?", "No", "También es el momento."),
     E("¿Conviene describir todos los detalles posibles?", "No", "Se eligen los que sirven.")],
    ("Elige uno de estos personajes: una niña muy curiosa, un niño tímido o un perro valiente. Escribe cuatro oraciones que lo muestren sin decir la palabra del rasgo (curiosa, tímido o valiente) y agrega dos detalles del ambiente donde está (un bosque de noche, un patio en verano o una cocina de mañana).", "Un niño tímido en un patio en verano: Se quedó junto a la reja y miraba jugar a los demás. Hacía calor y se oía el agua de una manguera.", ["elige un personaje de la lista", "muestra el rasgo con acciones o dichos", "incluye dos detalles del ambiente", "no usa la palabra del rasgo"], ["cuatro oraciones"], ["decir solo «era tímido»", "describir sin relación con la historia"], "Pide a otra persona que adivine qué rasgo tiene tu personaje."),
    "Escribe una acción que muestre que alguien tiene mucho frío.",
    "Describe en tres oraciones el patio de tu colegio en un día de lluvia.")

reg(
    OA13, 4,
    "Este cuaderno, lápiz y los cuentos escritos en los ejercicios. Sin materiales especiales.",
    "Aprenderé a escribir un desenlace que resuelva el conflicto de una manera coherente. Sirve para terminar el cuento de forma que tenga sentido.",
    ["Sé planificar un conflicto.", "Sé ordenar acciones con conectores."],
    ["El desenlace es la parte final del cuento. Ahí se resuelve el conflicto o se muestra cómo termina la situación. Un buen desenlace es coherente: tiene relación con lo que pasó antes. Si el problema era una pelota en el techo, el final debe hablar de cómo se recupera, no de algo que no tiene relación.",
     "Evita finales que borran todo, como «y todo fue un sueño», o que resuelven con un hecho mágico que nadie esperaba. Es mejor que el personaje use algo que hizo o aprendió en el desarrollo. Por ejemplo, si Mateo pidió ayuda al vecino, el final puede ser que el vecino lo ayuda y Mateo lo agradece.",
     "También puedes cerrar con lo que sintió o aprendió el personaje. El desenlace no tiene que ser largo: unas pocas oraciones bastan, pero deben dejar claro que la historia terminó."],
    [("desenlace", "parte final que resuelve el conflicto"), ("coherente", "que tiene relación con lo anterior"), ("resolver", "encontrar solución a un problema"), ("aprendizaje", "algo nuevo que se entiende o se sabe")],
    [("Elegir un final coherente", "Cuento: «Ana no podía dormir porque oía un ruido en la ventana. Se levantó y vio que era una rama que golpeaba el vidrio.» ¿Qué final es coherente: A) «Ana entendió que era la rama, se rio y volvió a dormir.» B) «Ana se convirtió en pájaro.»?", ["El problema era el ruido.", "A resuelve el ruido con lo que vio.", "B no tiene relación."], "A"),
     ("Usar lo del desarrollo", "En el desarrollo, Mateo pidió ayuda al vecino. ¿Qué final calza: «El vecino lo ayudó y Mateo le dio las gracias» o «Mateo compró otra casa»?", ["Lo que hizo antes fue pedir ayuda.", "El final debe usar eso.", "Elijo el primero."], "El vecino lo ayudó y Mateo le dio las gracias")],
    [("Terminar con «todo fue un sueño».", "Borra lo que pasó y no resuelve el problema.", "Resuelve usando lo que hizo el personaje."), ("Terminar con un hecho mágico inesperado.", "No tiene relación con el desarrollo.", "Haz que el final salga de las acciones del personaje.")],
    ([E("¿La parte final del cuento se llama inicio o desenlace?", "Desenlace", "Es donde termina la historia."),
      E("«Y todo fue un sueño» ¿resuelve el conflicto o lo borra?", "Lo borra", "Todo lo anterior queda sin efecto."),
      E("¿Un final coherente tiene relación con lo que pasó antes?", "Sí", "Eso lo hace coherente.")],
     [E("El problema era una pelota en un techo. ¿Qué final es mejor: «Recuperó la pelota con ayuda» o «Se fue de viaje a la luna»?", "Recuperó la pelota con ayuda", "Resuelve el problema."),
      E("¿Para qué sirve el desenlace?", "Para resolver el conflicto y cerrar la historia", "Muestra cómo termina."),
      E("Si Lola buscó a su gato por todo el parque, ¿qué final calza: «Lo encontró bajo un banco» o «Cambió de colegio»?", "Lo encontró bajo un banco", "Resuelve lo que buscaba.")],
     [E("Cuento: «Sofía perdió su bufanda en el parque y la buscó en la plaza.» ¿Qué final es coherente: A) «La encontró colgada de una reja y se la puso», B) «Sofía se fue a vivir a la luna», C) «Todo fue un sueño»?", "A", "A resuelve la pérdida; B es mágico y C borra la historia."),
      E("Cuento: «Pedro tenía miedo del perro del vecino. Un día le llevó un trozo de pan y el perro movió la cola.» ¿Qué final calza: «Pedro dejó de tener miedo» o «Pedro se volvió invisible»?", "Pedro dejó de tener miedo", "Sale de lo que hizo."),
      E("Cuento: «Camila no encontraba su lápiz. Revisó su mochila y su mesa.» ¿Qué final calza: «Lo halló bajo su cuaderno» o «Llegó un dragón»?", "Lo halló bajo su cuaderno", "Sigue la búsqueda.")],
     [E("Beto terminó su cuento así: «De pronto aparecieron mil hadas y arreglaron todo». ¿Qué problema tiene el final?", "No sale de lo que hizo el personaje", "Es una solución inesperada."),
      E("Un cuento dice que Ana tenía miedo a la oscuridad. ¿Qué final cierra mejor el conflicto: «Ana prendió su lámpara y ya no tuvo miedo» o «Ana comió un helado»?", "Ana prendió su lámpara y ya no tuvo miedo", "Resuelve el miedo.")],
     [E("Cuento: «Tomás perdió la llave de su casa. La buscó en el patio y en el bolsillo de su abrigo». ¿Qué desenlace es coherente: A) «La encontró en el pasto. Se alegró y entró a su casa», B) «Llegó un dragón y se llevó la casa», C) «Tomás compró un helado»?", "A", "A resuelve la pérdida de la llave; B y C no tienen relación con lo que buscaba."),
      E("Un desenlace puede cerrar con lo que aprendió el personaje. Mateo no podía bajar su pelota del techo y le pidió ayuda al vecino. Completa el final: «Mateo aprendió que pedir ___ no es malo.»", "Ayuda", "Pedir ayuda es lo que hizo en el cuento.")]),
    [E("Estás escribiendo la historia de un niño con una pelota en el techo. Quieres un final con aprendizaje. ¿Cuál escribes: «Aprendió a cuidar su pelota» o «Compró un helado»?", "Aprendió a cuidar su pelota", "Se relaciona con el problema.")],
    [E("¿El desenlace debe resolver el conflicto?", "Sí", "O mostrar cómo termina."),
     E("¿«Todo fue un sueño» es un buen final?", "No", "No resuelve el conflicto."),
     E("¿Un final puede tener un aprendizaje?", "Sí", "Cierra la historia.")],
    ("Lee este cuento: «Luis quería llegar a tiempo a la escuela, pero su bicicleta tenía una rueda desinflada. Pidió ayuda a una vecina, que le prestó una bomba de aire.» Escribe un desenlace de tres oraciones que resuelva el problema, use lo que hizo Luis y termine con lo que sintió o aprendió.", "Luis infló la rueda con la bomba. Llegó a tiempo a la escuela. Aprendió que pedir ayuda soluciona los problemas.", ["resuelve el problema de la rueda", "usa la bomba de la vecina", "tiene tres oraciones", "cierra con lo que sintió o aprendió"], ["desenlace de tres oraciones"], ["terminar con «fue un sueño»", "agregar algo mágico"], "Lee tu final a otra persona y pregúntale si resuelve el problema."),
    "Escribe un desenlace de una oración para: «Rosa tenía hambre y no encontraba su colación».",
    "Cambia el final de «Pedro y el perro del vecino» por otro coherente.")

reg(
    OA13, 5,
    "Este cuaderno, lápiz y el cuento escrito en los ejercicios. Sin materiales especiales.",
    "Aprenderé a revisar un cuento y a mejorar sus conectores y su secuencia. Sirve para que la historia se entienda y no tenga saltos.",
    ["Sé que un cuento tiene inicio, desarrollo y desenlace.", "Sé usar conectores de orden y causa."],
    ["Revisar es leer de nuevo un texto para mejorarlo. Al revisar un cuento, mira tres cosas. Primero, la secuencia: ¿las acciones están en un orden que se entiende? Segundo, los conectores: ¿unen las ideas y muestran el tiempo o la causa? Tercero, la coherencia: ¿cada parte tiene relación con la anterior?",
     "Un error frecuente es repetir «y luego» o «y después» muchas veces. Puedes cambiarlos por otros conectores: de pronto, entonces, por eso, mientras, al final. También puede faltar un conector y la historia da un salto, como «Salió de casa. Estaba en el cerro» sin explicar cómo llegó.",
     "Para revisar, lee tu cuento en voz alta o pídele a alguien que lo lea. Si se tropieza o no entiende, marca ese lugar. Luego arréglalo agregando un conector o cambiando el orden. Revisar no es empezar de nuevo, sino mejorar paso a paso."],
    [("revisar", "leer de nuevo un texto para mejorarlo"), ("secuencia", "orden en que ocurren los hechos"), ("salto", "cambio brusco que deja sin explicar lo que pasó entre medio"), ("coherencia", "relación lógica entre las partes del texto")],
    [("Corregir un salto", "Texto: «Lola salió de casa. Estaba en el cerro.» ¿Qué falta?", ["De la casa al cerro hay un camino.", "El lector no sabe cómo llegó.", "Falta una acción: caminó por el sendero."], "Una acción o un conector que cuente cómo llegó"),
     ("Cambiar conectores repetidos", "«Luis se levantó y luego se vistió y luego tomó desayuno y luego salió.» ¿Qué haces?", ["Se repite «y luego» tres veces.", "Cambio algunos conectores.", "Primero, después, finalmente."], "Cambiar por conectores distintos, como primero, después y al final")],
    [("Usar «y luego» todo el cuento.", "Aburre y no muestra causas.", "Varía los conectores."), ("No leer el cuento en voz alta.", "No notas los saltos.", "Léelo en voz alta o con otra persona.")],
    ([E("¿Revisar es lo mismo que empezar el cuento otra vez?", "No", "Es mejorar lo que ya escribiste."),
      E("¿Qué conector cambia «y luego» para mostrar causa: por eso o antes?", "Por eso", "Une causa y consecuencia."),
      E("«Lola salió de casa. Estaba en el cerro.» ¿Hay un salto?", "Sí", "Falta cómo llegó.")],
     [E("¿Cuáles son las tres cosas que se revisan en un cuento: secuencia, conectores y coherencia, o letra, color y tamaño?", "Secuencia, conectores y coherencia", "Esas tres permiten que la historia se entienda."),
      E("¿Para qué se lee el cuento en voz alta al revisarlo?", "Para notar saltos o partes que no se entienden", "Se escuchan los errores."),
      E("Si falta un conector entre dos ideas, ¿qué haces: lo agregas o borras todo?", "Lo agrego", "Se mejora paso a paso.")],
     [E("Texto: «Primero Sofía se levantó. Después se lavó la cara. Luego tomó desayuno. Finalmente fue al colegio.» ¿Cuántos conectores de orden hay?", "4", "Son primero, después, luego y finalmente."),
      E("Mejora la oración «Tenía sed y tomó agua». ¿Cuál une la causa y la consecuencia: A) «Tenía sed, por eso tomó agua», B) «Tenía sed, mientras tomó agua»?", "A", "«Por eso» une la causa (sed) con la consecuencia (tomar agua)."),
      E("Texto: «Mateo cayó. Se levantó. Le dolía la rodilla.» ¿Qué orden de acciones es más lógico: caer, levantarse, dolerle, o dolerle, caer, levantarse?", "Caer, levantarse, dolerle", "Es la secuencia natural.")],
     [E("Beto dice: «Mi cuento está listo porque tiene diez oraciones». ¿Qué debe revisar además del número?", "Que haya secuencia, conectores y coherencia", "Tener muchas oraciones no garantiza que se entienda."),
      E("Texto: «Ema perdió su lápiz. Entonces fue al mar». ¿Qué falla: la coherencia o la tilde?", "La coherencia", "No hay relación entre perder el lápiz e ir al mar.")],
     [E("Mejora «Juan fue a la plaza y luego jugó y luego comió». ¿Cuál versión usa conectores variados: A) «Primero Juan fue a la plaza, después jugó y al final comió», B) «Juan fue a la plaza y luego jugó y luego comió y luego durmió»?", "A", "A cambia «y luego» por primero, después y al final; B repite «y luego»."),
      E("Un cuento une cinco acciones con conectores entre cada par. ¿Cuántos conectores se necesitan entre ellas?", "4", "Entre cinco acciones hay cuatro uniones.")]),
    [E("Lees tu cuento en voz alta y notas que pasas de la casa al cerro sin contar cómo. ¿Qué haces: agregar una acción o cambiar el título?", "Agregar una acción", "Así se evita el salto.")],
    [E("¿Se puede mejorar un cuento cambiando conectores?", "Sí", "Los conectores muestran orden y causa."),
     E("¿Un salto es una parte que falta explicar?", "Sí", "El lector no entiende qué pasó entre medio."),
     E("¿Revisar es leer de nuevo para mejorar?", "Sí", "Eso es revisar.")],
    ("Revisa este cuento: «Ana fue al río. Y luego vio un pez. Y luego estaba cansada. Y luego llegó a su casa». Reescríbelo con conectores distintos (primero, de pronto, por eso, al final) y agrega la acción que explica por qué estaba cansada y cómo volvió.", "Primero, Ana fue al río. De pronto vio un pez que saltaba. Corrió tras él, por eso quedó cansada. Al final volvió caminando a su casa.", ["usa al menos tres conectores distintos", "agrega la causa del cansancio", "explica cómo volvió", "mantiene el orden"], ["cuento reescrito"], ["repetir «y luego»", "dejar saltos"], "Léelo en voz alta y comprueba si se tropieza en algún lugar."),
    "Reescribe «Pedro comió y luego durmió y luego jugó» con conectores distintos.",
    "Lee uno de tus cuentos y marca un salto que arreglarías.")

# ================================================================ OA 14 · escribir artículos informativos
reg(
    OA14, 1,
    "Este cuaderno, lápiz y los temas escritos en los ejercicios. Sin materiales especiales.",
    "Aprenderé a elegir un tema pequeño y a pensar en quién leerá mi artículo. Sirve para escribir un texto claro que explique algo.",
    ["Sé que los textos informativos entregan datos.", "Sé escribir una pregunta de investigación."],
    ["Un artículo informativo es un texto que explica un tema para que el lector aprenda. Antes de escribir, hay que delimitar el tema, es decir, hacerlo más pequeño y concreto. «Los animales» es demasiado grande. «Las ballenas» es más chico. «Qué comen las ballenas» es lo bastante pequeño para un artículo corto.",
     "También hay que pensar en el lector. No se escribe igual para un niño de seis años que para un curso de tercero. El lector define qué palabras usar, cuántos datos incluir y qué hay que explicar. Si el lector no conoce una palabra, se explica con una definición breve.",
     "Un artículo claro empieza con el tema y avanza con datos ordenados. Un buen modo de comenzar es escribir el tema, el lector y una pregunta que el artículo responderá. Por ejemplo: tema, el agua; lector, mi curso; pregunta, ¿en qué estados puede estar el agua?"],
    [("artículo informativo", "texto que explica un tema para que el lector aprenda"), ("tema", "asunto del que trata el texto"), ("delimitar", "hacer un tema más pequeño y preciso"), ("lector", "persona para quien se escribe el texto")],
    [("Delimitar el tema", "Tema: «El agua». ¿Qué tema más pequeño sirve: «Los estados del agua» o «Todo sobre la Tierra»?", ["El agua es un tema grande.", "Los estados del agua es una parte.", "Elijo «Los estados del agua»."], "Los estados del agua"),
     ("Pensar en el lector", "Escribes sobre el agua para niños de primero. ¿Usas «los estados de agregación» o «el agua puede ser líquida, hielo o vapor»?", ["Los niños de primero no conocen palabras difíciles.", "La segunda es simple.", "Elijo la segunda."], "El agua puede ser líquida, hielo o vapor")],
    [("Elegir un tema tan grande que no se puede explicar.", "No cabe en un artículo corto.", "Hazlo más chico y concreto."), ("Escribir sin pensar en el lector.", "Quizás use palabras que no entiende.", "Pregunta: ¿para quién escribo?")],
    ([E("«Los animales» ¿es un tema muy grande o un tema pequeño?", "Muy grande", "Incluye miles de animales."),
      E("¿Qué texto explica un tema para que el lector aprenda: un artículo informativo o un cuento?", "Un artículo informativo", "Su propósito es informar."),
      E("¿Cuál tema es más pequeño: «El agua» o «Los estados del agua»?", "Los estados del agua", "Es una parte del tema grande.")],
     [E("¿Qué significa delimitar un tema?", "Hacerlo más pequeño y preciso", "Así cabe en un texto corto."),
      E("¿Por qué hay que pensar en el lector antes de escribir?", "Para decidir qué palabras usar y qué explicar", "El lector define el lenguaje."),
      E("Si el lector no conoce una palabra, ¿qué haces: la explicas o la borras?", "La explico", "Con una definición breve.")],
     [E("Tema grande: «Los deportes». ¿Cuál es un tema más chico: «El fútbol» o «Los deportes del mundo»?", "El fútbol", "Es un deporte entre muchos."),
      E("Tema: «Las plantas». ¿Cuál es una pregunta pequeña: «¿Qué necesitan las plantas para crecer?» o «¿Todo sobre las plantas?»", "¿Qué necesitan las plantas para crecer?", "Es una pregunta precisa."),
      E("Escribes para tu curso. ¿Cuál de estas oraciones es más simple: «El agua se evapora al calentarse» o «La fase de transición se produce por entalpía»?", "El agua se evapora al calentarse", "Usa palabras que un curso de tercero entiende.")],
     [E("Ana quiere escribir un artículo «Todo sobre los océanos». ¿Qué problema tiene su tema?", "Es demasiado grande", "No cabe en un artículo corto."),
      E("Un artículo para niños de primero dice «La hidratación celular es esencial». ¿Qué falla?", "Usa palabras que el lector no conoce", "No pensó en el lector.")],
     [E("Delimita el tema «Los insectos» eligiendo uno más pequeño: «Las abejas» o «Todos los seres vivos».", "Las abejas", "Es un tipo de insecto."),
      E("Un plan dice: tema, los volcanes; lector, mi curso. ¿Qué parte del plan falta: la pregunta que responderá el artículo o el nombre del autor?", "La pregunta que responderá el artículo", "El plan tiene tema, lector y pregunta.")]),
    [E("Tu curso estudia los volcanes. Para escribir un artículo corto, ¿qué tema eliges: «Los volcanes» o «Qué sale de un volcán cuando entra en erupción»?", "Qué sale de un volcán cuando entra en erupción", "Es más pequeño y concreto.")],
    [E("¿Un artículo informativo explica un tema?", "Sí", "Es su propósito."),
     E("¿Un tema grande se puede delimitar?", "Sí", "Se hace más pequeño."),
     E("¿El lector influye en las palabras que uso?", "Sí", "Debo usar palabras que entienda.")],
    ("Elige uno de estos temas grandes: los insectos, las plantas o el agua. Escribe: (1) el tema delimitado, (2) para quién escribes (por ejemplo, niños de primero o tu curso) y (3) la pregunta que responderá tu artículo.", "Tema grande: las plantas. Tema: qué necesitan las plantas para crecer. Lector: niños de primero. Pregunta: ¿qué necesitan las plantas para crecer?", ["elige un tema de la lista", "lo delimita a algo más pequeño", "define el lector", "escribe una pregunta clara"], ["tres líneas con tema, lector y pregunta"], ["dejar el tema muy grande", "no pensar en el lector"], "Lee tu plan a otra persona y pregúntale si el tema es lo bastante pequeño."),
    "Elige un animal y escribe un tema pequeño sobre él.",
    "Escribe dos temas delimitados distintos para «el mar».")

reg(
    OA14, 2,
    "Este cuaderno, lápiz y la lista de datos escrita en los ejercicios. Sin materiales especiales.",
    "Aprenderé a agrupar datos en subtemas para organizar mi artículo. Sirve para que las ideas queden ordenadas y sea fácil leerlas.",
    ["Sé delimitar un tema.", "Sé que un texto tiene partes."],
    ["Cuando juntas datos, es fácil que queden desordenados. Para organizarlos, se agrupan por subtema. El subtema es una parte del tema. Por ejemplo, el tema «El agua» puede tener los subtemas «Usos del agua» y «Estados del agua».",
     "Para agrupar, lee cada dato y pregúntate de qué subtema habla. Los datos que hablan de lo mismo van juntos. Un dato que no pertenece a ningún subtema se deja fuera o se cambia. Cada subtema puede ser un párrafo del artículo.",
     "Ponle un título o una frase que resuma cada grupo. Así tu artículo tendrá un orden claro: el lector sabe qué va a encontrar en cada parte. Un buen artículo no es una lista de datos mezclados."],
    [("subtema", "parte del tema que agrupa datos relacionados"), ("agrupar", "juntar lo que se parece o tiene relación"), ("dato", "información concreta"), ("párrafo", "conjunto de oraciones sobre una misma idea")],
    [("Agrupar datos", HECHOS_AGUA + " ¿Cuáles datos pertenecen al subtema «Usos del agua»?", ["Busco los datos que dicen para qué se usa.", "a) beber, c) regar, e) lavar, g) cocinar.", "Esos son los usos."], "a, c, e, g"),
     ("Poner título al grupo", HECHOS_AGUA + " Los datos b, d, f y h hablan de hielo, vapor, líquido y derretirse. ¿Qué título les pones?", ["Los cuatro hablan de cómo está el agua.", "El hielo es sólido, el vapor es gas, el vaso es líquido.", "El título: Estados del agua."], "Estados del agua")],
    [("Mezclar datos de subtemas distintos en el mismo grupo.", "El lector se confunde.", "Pregúntate de qué habla cada dato."), ("Hacer una lista larga sin grupos.", "No se ve el orden.", "Agrupa y pon un título a cada grupo.")],
    ([E(HECHOS_AGUA + " El dato a) «El agua se usa para beber», ¿es de usos o de estados del agua?", "Usos", "Dice para qué se usa."),
      E(HECHOS_AGUA + " El dato b) «El hielo es agua en estado sólido», ¿es de usos o de estados?", "Estados", "Habla de cómo está el agua."),
      E("¿Cómo se llama una parte del tema que agrupa datos relacionados?", "Subtema", "Es un grupo dentro del tema.")],
     [E("¿Para qué sirve agrupar los datos por subtema?", "Para ordenar las ideas del artículo", "Cada grupo puede ser un párrafo."),
      E(HECHOS_AGUA + " ¿Cuántos datos hay en total?", "8", "Van de la a) a la h)."),
      E("Un dato no pertenece a ningún subtema del artículo. ¿Lo dejas fuera o lo mezclas?", "Lo dejo fuera", "No ayuda al orden.")],
     [E(HECHOS_AGUA + " ¿Cuáles datos van en «Estados del agua»?", "b, d, f, h", "Hablan de hielo, vapor, líquido y derretirse."),
      E(HECHOS_AGUA + " ¿Cuántos datos van en «Usos del agua»?", "4", "Son a, c, e y g."),
      E(HECHOS_AGUA + " Dato e) «Con agua se lava la ropa», ¿a qué subtema pertenece?", "Usos del agua", "Habla de para qué sirve.")],
     [E("Dos subtemas posibles para el tema «Las plantas»: «Partes de la planta» y «Cuidados». El dato «Las plantas necesitan agua y luz» ¿va en partes o en cuidados?", "Cuidados", "Dice lo que necesitan para vivir."),
      E("Un grupo mezcla «el hielo es sólido» y «con agua se lava la ropa». ¿Qué problema tiene?", "Mezcla datos de subtemas distintos", "Uno es de estados y otro de usos.")],
     [E("Tema «Las mascotas». Datos: 1) El perro necesita paseos. 2) El gato necesita arena limpia. 3) Los perros se reconocen por su ladrido. Subtema «Cuidados». ¿Qué datos van en él?", "1 y 2", "Hablan de lo que necesitan."),
      E("Un grupo tiene los datos «El hielo es sólido», «El vapor es gas» y «El agua líquida se mueve». ¿Qué título le pones: «Estados del agua» o «Usos del agua»?", "Estados del agua", "Los tres hablan de cómo está el agua.")]),
    [E("Quieres escribir sobre el agua para tu curso. Tienes 8 datos y dos subtemas. ¿Qué haces primero: agrupar los datos o escribir el título?", "Agrupar los datos", "Así ordenas la información.")],
    [E("¿Los datos que hablan de lo mismo van juntos?", "Sí", "Forman un subtema."),
     E("¿Cada subtema puede ser un párrafo?", "Sí", "Así se ordena el artículo."),
     E("¿Una lista de datos mezclados es un buen artículo?", "No", "Le falta orden y subtemas.")],
    ("Agrupa estos datos sobre el tema «Las abejas» en dos subtemas: «Qué hacen» y «Dónde viven». Datos: a) Las abejas obreras recogen néctar. b) Las abejas viven en colmenas. c) Las abejas hacen miel con el néctar. d) Algunas abejas viven en huecos de árboles. e) Las abejas visitan las flores. f) Las colmenas se instalan en lugares protegidos. Escribe cada grupo con su título.", "Qué hacen: a, c, e. Dónde viven: b, d, f.", ["forma dos grupos", "cada dato va en el grupo correcto", "pone título a cada grupo", "no deja datos sin agrupar"], ["dos grupos con título"], ["mezclar los grupos", "dejar datos afuera"], "Compara tus grupos con otra persona y explícale tus decisiones."),
    "Agrupa estos tres datos en dos subtemas, «Sonidos» y «Cuidados»: el perro ladra, el gato maúlla, el perro necesita paseos. Escribe qué datos van en cada subtema.",
    "Escribe tres datos de un tema que te guste y ponles un título.")

reg(
    OA14, 3,
    "Este cuaderno, lápiz y los párrafos escritos en los ejercicios. Sin materiales especiales.",
    "Aprenderé a escribir párrafos con una idea central y datos que la apoyan. Sirve para que cada párrafo trate de una sola cosa y se entienda.",
    ["Sé agrupar datos en subtemas.", "Sé que un párrafo tiene varias oraciones."],
    ["Un párrafo es un conjunto de oraciones que hablan de una misma idea. Esa idea se llama idea central. Suele escribirse en la primera oración. Las demás oraciones dan detalles, explicaciones o datos que apoyan esa idea.",
     "Por ejemplo: «Las plantas necesitan agua. Sus raíces absorben agua del suelo. Sin agua, las hojas se secan». La idea central es que las plantas necesitan agua. Las otras dos oraciones la apoyan. Si agregáramos «Mi tío tiene un gato», no pertenecería al párrafo, porque habla de otra cosa.",
     "Para escribir un párrafo, primero elige la idea central. Después busca dos o tres datos que la expliquen. Cada párrafo nuevo empieza en una línea nueva. Revisa que ninguna oración se salga del tema."],
    [("párrafo", "conjunto de oraciones sobre una misma idea"), ("idea central", "idea principal de un párrafo"), ("apoyar", "dar razones o datos que explican una idea"), ("oración", "conjunto de palabras que expresa una idea completa")],
    [("Encontrar la idea central", "Párrafo: «Las plantas necesitan agua. Sus raíces absorben agua del suelo. Sin agua, las hojas se secan.» ¿Cuál es la idea central?", ["Es la idea de la que hablan todas las oraciones.", "La primera dice que necesitan agua.", "Las otras la explican."], "Las plantas necesitan agua"),
     ("Quitar lo que sobra", "Párrafo: «Las plantas necesitan agua. Sus raíces absorben agua del suelo. Mi tío tiene un gato. Sin agua, las hojas se secan.» ¿Qué oración sobra?", ["Busco la que no habla de las plantas.", "La del tío y su gato.", "Esa oración sobra."], "Mi tío tiene un gato")],
    [("Escribir muchas ideas en un solo párrafo.", "El lector se pierde.", "Una idea central por párrafo."), ("Agregar oraciones que no tienen relación.", "Rompen el tema.", "Revisa que todas apoyen la idea central.")],
    ([E("«Las plantas necesitan agua. Sus raíces absorben agua del suelo.» ¿Cuál es la idea central?", "Las plantas necesitan agua", "Es la oración que dice la idea general."),
      E("¿Cómo se llama el conjunto de oraciones sobre una misma idea?", "Párrafo", "Cada párrafo trata de una idea."),
      E("¿Dónde suele escribirse la idea central: en la primera oración o al azar?", "En la primera oración", "Así el lector sabe de qué trata.")],
     [E("¿Para qué sirven las demás oraciones de un párrafo?", "Para apoyar o explicar la idea central", "Dan detalles y datos."),
      E("Una oración habla de otra cosa que no es el tema del párrafo. ¿La dejas o la sacas?", "La saco", "Rompe el orden."),
      E("Cuando empiezas un nuevo párrafo, ¿escribes en la misma línea o en una línea nueva?", "En una línea nueva", "Así se separan las ideas.")],
     [E("Idea central: «Los perros necesitan paseos». ¿Qué oración la apoya: «Caminar los mantiene sanos» o «Los gatos duermen mucho»?", "Caminar los mantiene sanos", "Explica por qué necesitan paseos."),
      E("Párrafo: «El hielo es agua sólida. Se derrite con el calor. El vapor es otra forma del agua. Mi vecina tiene un auto rojo.» ¿Qué oración sobra?", "Mi vecina tiene un auto rojo", "No habla del agua."),
      E("Quieres un párrafo sobre las abejas obreras. ¿Qué oración sirve como idea central: A) «Las abejas obreras trabajan en la colmena», B) «Mi primo juega fútbol», C) «Una abeja obrera bate sus alas»?", "A", "A resume todo el párrafo; C es un solo detalle y B es de otro tema.")],
     [E("Tomás escribió un párrafo con tres ideas distintas mezcladas. ¿Qué debe hacer: dividirlo en párrafos o borrar todo?", "Dividirlo en párrafos", "Cada idea va en su párrafo."),
      E("Mía dice que un párrafo puede empezar con una oración que no se relaciona con el resto. ¿Tiene razón?", "No", "Todas las oraciones deben apoyar la misma idea.")],
     [E("Un párrafo empieza con la idea central «El agua se puede congelar». ¿Qué oración lo continúa mejor: A) «Con mucho frío se vuelve hielo», B) «Mi tía tiene un auto rojo», C) «Las nubes son blancas»?", "A", "A da un dato que apoya la idea; B y C se salen del tema."),
      E("Un párrafo tiene cinco oraciones; una de ellas es la idea central y una sobra. ¿Cuántas apoyan la idea central?", "3", "Cinco menos la central y la que sobra.")]),
    [E("Escribes sobre las abejas: «Las abejas obreras recogen néctar. Lo llevan a la colmena. Mi primo juega fútbol.» ¿Qué oración tachas?", "Mi primo juega fútbol", "No habla de las abejas.")],
    [E("¿Un párrafo trata de una idea central?", "Sí", "Las oraciones la apoyan."),
     E("¿Una oración que se sale del tema debe quedar?", "No", "Se saca del párrafo."),
     E("¿Cada párrafo nuevo empieza en una línea nueva?", "Sí", "Así se separan las ideas.")],
    ("Escribe un párrafo de cuatro oraciones sobre uno de estos temas: las plantas necesitan luz, los perros necesitan agua o las abejas viven en colmenas. La primera oración debe ser la idea central. Las otras tres deben apoyarla con datos.", "Las plantas necesitan luz. Las hojas la usan para crecer. Sin luz se ponen pálidas. Por eso conviene ponerlas cerca de una ventana.", ["elige una de las tres ideas", "la primera oración es la idea central", "las otras apoyan la idea", "ninguna oración se sale del tema"], ["párrafo de cuatro oraciones"], ["mezclar ideas", "olvidar la idea central"], "Pide a otra persona que diga cuál es la idea central de tu párrafo."),
    "Escribe una idea central y un dato que la apoye sobre las abejas.",
    "Toma un párrafo tuyo y subraya la idea central.")

reg(
    OA14, 4,
    "Este cuaderno, lápiz y las definiciones escritas en los ejercicios. Sin materiales especiales.",
    "Aprenderé a explicar un concepto con una definición y un ejemplo. Sirve para que el lector entienda una palabra nueva de mi artículo.",
    ["Sé escribir párrafos con idea central.", "Sé qué es una definición."],
    ["Cuando un artículo usa una palabra nueva, hay que explicarla. Para eso se usa una definición, que dice qué es algo, y un ejemplo, que muestra un caso concreto. Por ejemplo: «Un mamífero es un animal que alimenta a sus crías con leche. Por ejemplo, el perro, la vaca y la ballena son mamíferos».",
     "Los ejemplos ayudan a comprender, porque conectan la idea con algo conocido. Se anuncian con expresiones como «por ejemplo» o «como». Otro caso: «Un insecto es un animal con seis patas, como la abeja, la mosca y la hormiga».",
     "Para escribir una buena explicación, primero define con palabras simples y luego da uno o dos ejemplos que sean correctos. Un ejemplo debe cumplir lo que dice la definición. Si no, confunde. Por eso hay que revisar que el ejemplo calce con la definición."],
    [("definición", "explicación de lo que es algo"), ("ejemplo", "caso concreto que muestra una idea"), ("mamífero", "animal que alimenta a sus crías con leche"), ("insecto", "animal pequeño con seis patas")],
    [("Definición y ejemplo", "Explica «insecto»: ¿qué definición y qué ejemplo sirven?", ["Defino: animal con seis patas.", "Busco un caso que cumpla: la abeja.", "Uno las dos partes."], "Un insecto es un animal con seis patas, por ejemplo la abeja"),
     ("Revisar el ejemplo", "«Un mamífero es un animal que alimenta a sus crías con leche, por ejemplo la ballena.» ¿El ejemplo calza?", ["La ballena alimenta a sus crías con leche.", "Cumple la definición.", "El ejemplo calza."], "Sí, calza")],
    [("Dar un ejemplo que no cumple la definición.", "Confunde al lector.", "Revisa que el ejemplo calce."), ("Dar solo la definición sin ejemplo.", "Puede costar entender.", "Agrega un caso concreto.")],
    ([E("Un insecto tiene seis patas. ¿La abeja es un buen ejemplo de insecto? Responde sí o no.", "Sí", "Es un animal con seis patas."),
      E("¿Qué expresión anuncia un ejemplo: «por ejemplo» o «sin embargo»?", "Por ejemplo", "Introduce un caso concreto."),
      E("¿La definición dice qué es algo o da un caso?", "Dice qué es algo", "El ejemplo da un caso.")],
     [E("¿Para qué sirve un ejemplo en un artículo?", "Para que el lector entienda con un caso concreto", "Conecta la idea con algo conocido."),
      E("Un mamífero alimenta a sus crías con leche. ¿Cuál es ejemplo de mamífero: la vaca o la mosca?", "La vaca", "La mosca es un insecto."),
      E("¿Un ejemplo debe cumplir la definición?", "Sí", "Si no, confunde.")],
     [E("¿Cuál es una definición con ejemplo correcta para «reciclar»: A) «Reciclar es volver a usar un material, por ejemplo el papel», B) «Reciclar es botar un material a la calle, por ejemplo el papel», C) «Reciclar es el papel»?", "A", "La definición dice qué es y el ejemplo cumple lo que dice; B cambia el sentido y C no define."),
      E("Completa: «Un insecto es un animal con ___ patas, como la hormiga.»", "Seis", "Los insectos tienen seis patas."),
      E("Completa: «Un mamífero es un animal que alimenta a sus crías con ___, como el perro.»", "Leche", "Esa es la definición de mamífero.")],
     [E("Ema escribió: «Un insecto es un animal con seis patas, por ejemplo el perro». ¿Qué falla?", "El perro no es un insecto; tiene cuatro patas", "El ejemplo no cumple la definición."),
      E("Beto dice que un buen ejemplo de mamífero es la mosca. ¿Tiene razón?", "No", "La mosca es un insecto, no alimenta con leche.")],
     [E("¿Qué ejemplo calza con «Una herramienta es un objeto que sirve para hacer un trabajo»: la pala o la manzana?", "La pala", "La pala sirve para hacer un trabajo; la manzana no es una herramienta."),
      E("En «Una fruta es la parte de una planta que contiene semillas, como la manzana», ¿cuál es el ejemplo?", "La manzana", "Aparece después de «como».")]),
    [E("Escribes un artículo para tu curso y usas la palabra «mamífero». ¿Qué agregas para que se entienda: una definición con ejemplo o un dibujo sin explicación?", "Una definición con ejemplo", "Explica la palabra nueva.")],
    [E("¿Una definición explica qué es algo?", "Sí", "Dice su significado."),
     E("¿Un ejemplo es un caso concreto?", "Sí", "Muestra la idea con algo real."),
     E("¿«Por ejemplo» introduce un caso?", "Sí", "Anuncia el ejemplo.")],
    ("Escribe una explicación de cuatro oraciones sobre la palabra «mamífero» o «insecto». Debe tener: una definición, dos ejemplos que cumplan la definición y una oración que diga por qué sirven esos ejemplos.", "Un insecto es un animal con seis patas. Por ejemplo, la abeja y la hormiga. Ambos tienen seis patas. Por eso son insectos.", ["incluye una definición", "da dos ejemplos correctos", "usa «por ejemplo» o «como»", "explica por qué calzan"], ["cuatro oraciones"], ["dar un ejemplo que no calza", "omitir la definición"], "Pide a otra persona que diga si los ejemplos cumplen la definición."),
    "Escribe una definición con ejemplo para «reciclar».",
    "Escribe dos ejemplos nuevos de mamíferos.")

reg(
    OA14, 5,
    "Este cuaderno, lápiz y los textos escritos en los ejercicios. Sin materiales especiales.",
    "Aprenderé a revisar el orden y la precisión de un artículo informativo. Sirve para que el texto sea claro y no tenga datos vagos o equivocados.",
    ["Sé escribir párrafos con idea central.", "Sé definir y dar ejemplos."],
    ["Al revisar un artículo, mira primero el orden. Un artículo suele tener un comienzo que presenta el tema, un desarrollo con párrafos que explican cada subtema y un cierre que resume. Si los párrafos están en otro orden, el lector se pierde.",
     "Después revisa la precisión: ¿los datos son exactos y las palabras son concretas? Palabras como «cosas» o «muchos» no dicen nada preciso. Es mejor escribir «hielo, vapor y agua líquida» que «cosas del agua». Un dato incorrecto, como decir que el hielo es agua líquida, debe corregirse.",
     "Por último, lee el texto como lo leería un lector que no conoce el tema. Si algo no se entiende, agrega una definición o un ejemplo. Corrige un aspecto cada vez para no perderte."],
    [("precisión", "decir las cosas con exactitud"), ("vago", "poco claro o poco concreto"), ("cierre", "parte final que resume lo dicho"), ("desarrollo", "parte central que explica el tema")],
    [("Reemplazar una palabra vaga", "«El agua tiene cosas diferentes.» ¿Cómo lo dices con precisión?", ["«Cosas» no dice nada.", "Sé que el agua puede ser líquida, sólida o gas.", "Escribo: El agua puede ser líquida, sólida o gaseosa."], "El agua puede ser líquida, sólida o gaseosa"),
     ("Corregir un dato", "«El hielo es agua líquida.» ¿Está bien?", ["El hielo es agua congelada.", "Es agua en estado sólido.", "Corrijo: El hielo es agua sólida."], "No; el hielo es agua sólida")],
    [("Usar palabras vagas como «cosas» o «muchos».", "No informan.", "Cambia por datos concretos."), ("Dejar un dato equivocado.", "Enseña algo falso.", "Revisa cada dato antes de entregar.")],
    ([E("¿Qué palabra es vaga: «cosas» o «hielo»?", "Cosas", "No dice qué son."),
      E("¿Qué parte de un artículo presenta el tema: el comienzo o el cierre?", "El comienzo", "Ahí se presenta."),
      E("¿El hielo es agua sólida o líquida?", "Sólida", "El hielo es agua congelada.")],
     [E("¿Qué significa escribir con precisión?", "Decir las cosas con exactitud", "Evita datos vagos o equivocados."),
      E("Si los párrafos están desordenados, ¿qué ocurre con el lector?", "Se pierde", "No sigue las ideas."),
      E("¿Para qué sirve el cierre de un artículo?", "Para resumir lo dicho", "Deja una idea final clara.")],
     [E("Cambia «muchas cosas» por una expresión precisa: «El agua se usa para beber, regar, lavar y cocinar». ¿Cuántos usos se nombran?", "4", "Son beber, regar, lavar y cocinar."),
      E("Ordena: 1) Cierre. 2) Presentación del tema. 3) Desarrollo. Escribe los números en orden del artículo.", "2, 3, 1", "Primero se presenta, luego se explica y al final se resume."),
      E("«El vapor es agua en estado gaseoso.» ¿Es un dato exacto?", "Sí", "El vapor es agua convertida en gas.")],
     [E("Beto escribió: «Hay muchas cosas que se hacen con agua». ¿Qué mejora propones: nombrar los usos concretos, como beber y regar, o escribir más «cosas»?", "Nombrar los usos concretos, como beber y regar", "Reemplaza lo vago por datos concretos."),
      E("Un artículo dice: «El hielo es agua líquida». Lola lo corrigió a «sólida». ¿Mejoró su precisión?", "Sí", "Ahora el dato es correcto.")],
     [E("¿Cuál reescribe con precisión «Las plantas necesitan cosas para vivir»: A) «Las plantas necesitan agua, luz y aire para vivir», B) «Las plantas necesitan algunas cosas importantes»?", "A", "A nombra datos concretos; B sigue siendo vago."),
      E("Un artículo tiene tres párrafos: cierre, desarrollo, presentación. ¿Cuál debe ir en la segunda posición?", "El desarrollo", "Va entre la presentación y el cierre.")]),
    [E("Revisas el artículo de un amigo: «El agua es importante porque se usa en cosas». ¿Qué le sugieres: nombrar los usos o agregar más «cosas»?", "Nombrar los usos", "Hace el texto más preciso.")],
    [E("¿Un artículo debe tener un orden claro?", "Sí", "Presentación, desarrollo y cierre."),
     E("¿«Cosas» es una palabra precisa?", "No", "Es una palabra vaga."),
     E("¿Revisar sirve para corregir datos equivocados?", "Sí", "Así el texto enseña lo correcto.")],
    ("Revisa este texto: «El agua tiene cosas diferentes. El hielo es agua líquida. Muchas personas usan el agua». Reescríbelo en tres oraciones precisas: nombra los estados del agua, corrige el dato del hielo y escribe dos usos concretos.", "El agua puede ser líquida, sólida o gaseosa. El hielo es agua sólida. Las personas usan el agua para beber y cocinar.", ["nombra los tres estados", "corrige el dato del hielo", "nombra dos usos concretos", "evita palabras vagas"], ["tres oraciones corregidas"], ["dejar «cosas»", "mantener el dato equivocado"], "Lee tu versión a otra persona y pregúntale si algo le suena vago."),
    "Cambia «Hay cosas en el cielo» por una oración con datos concretos.",
    "Elige un texto tuyo y reemplaza una palabra vaga por una precisa.")
